/**
 * The live's numbers, each the ONE copy (docs/wiki/services/lives.md).
 *
 * Clients carry none of them: `GET /api/lives/limits` publishes them, for the reason
 * `reel.constants.ts` gives - an installed APK keeps whatever it was built with.
 */

/** The live key: 32 random bytes, generated by the broadcaster's client, carried as 64 hex chars. */
export const LIVE_KEY_HEX_RE = /^[0-9a-f]{64}$/;

/**
 * The largest sealed segment the server accepts, in bytes. A segment is a few seconds of 720p at
 * ~2.5 Mb/s (about 1 MB for 3 s), so 4 MiB is generous and stays half the 8 MiB request-body
 * invariant of the media session routes (media-streaming-upload.md, section 3.2).
 */
export const LIVE_SEGMENT_MAX_BYTES = 4 * 1024 * 1024;

/**
 * Q5 (live.md): after this long with no segment, the live is ENDED by the sweep, durably
 * (`endReason = 'dropped'`). What viewers show meanwhile ("reconnecting") is theirs to decide from
 * `lastSegmentAt` and `serverNow` in the manifest; the END is this row's state, never a client timer.
 * To be confirmed on the WP-L1 bench.
 */
export const LIVE_RECONNECT_WINDOW_MS = 60_000;

/** L4 (live.md): a first-version live lasts at most an hour; past it, the live is ended. */
export const LIVE_MAX_DURATION_MS = 60 * 60_000;

/** How many segments one manifest answer lists at most - a viewer polls from its last index. */
export const LIVE_MANIFEST_WINDOW = 10;

/** Why a live ended - the `endReason` column. */
export type LiveEndReason = 'broadcaster' | 'dropped' | 'max_duration' | 'erased';

/** The numbers as the API serves them. */
export function liveLimits(): {
  segmentMaxBytes: number;
  reconnectWindowMs: number;
  maxDurationMs: number;
  manifestWindow: number;
} {
  return {
    segmentMaxBytes: LIVE_SEGMENT_MAX_BYTES,
    reconnectWindowMs: LIVE_RECONNECT_WINDOW_MS,
    maxDurationMs: LIVE_MAX_DURATION_MS,
    manifestWindow: LIVE_MANIFEST_WINDOW,
  };
}
